package com.mockarena.assessment.application; import com.mockarena.assessment.domain.*; import com.mockarena.assessment.infrastructure.question.McqEvaluationData; import java.math.*;
public final class McqScorer {private McqScorer(){}public record Score(EvaluationOutcome outcome,BigDecimal awarded,BigDecimal max){}public static Score score(String selected,McqEvaluationData data){BigDecimal correct=BigDecimal.valueOf(data.scoringPolicy().path("parameters").path("correctPoints").asInt(1));BigDecimal incorrect=BigDecimal.valueOf(data.scoringPolicy().path("parameters").path("incorrectPoints").asInt(0));BigDecimal unanswered=BigDecimal.valueOf(data.scoringPolicy().path("parameters").path("unansweredPoints").asInt(0));if(selected==null||selected.isBlank())return new Score(EvaluationOutcome.UNANSWERED,unanswered,correct);return selected.equals(data.correctOptionId())?new Score(EvaluationOutcome.CORRECT,correct,correct):new Score(EvaluationOutcome.INCORRECT,incorrect,correct);}}
